const p = $json;
const price = Number(p.price).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
const caption = [
  `🧸 Achadinho para o feed!`,
  p.title,
  `Por apenas ${price} hoje.`,
  p.rating != null ? `⭐ ${p.rating}` : null,
  p.sold_count != null ? `🛒 +${Number(p.sold_count).toLocaleString('pt-BR')} vendidos` : null,
  p.ai_content_angle ? `Ângulo: ${p.ai_content_angle}` : null,
  '',
  'Link na bio / marcação do produto quando elegível.',
  '#achadinhos #maternidade #kids'
].filter((x) => x !== null).join('\n');

return [{ json: { ...p, caption } }];
